async function main() {
  console.log("Seeding universities...");
  let count = 0;

  for (const u of UNIVERSITIES_DATA) {
    try {
      await prisma.university.upsert({
        where: { name: u.university_name },
        update: {},
        create: {
          name: u.university_name,
          // If your Prisma schema supports these extra fields, uncomment them:
          // abbreviation: u.abbreviation,
          // officialWebsite: u.official_website,
          // logoUrl: u.logo_url ?? null,
          // universityType: u.university_type,
          // city: u.city,
          // province: u.province,
          // campuses: u.campuses,
        },
      });
      count++;
    } catch (e) {
      console.error(`Failed to add ${u.university_name}:`, e);
    }
  }

  console.log(`Successfully seeded ${count} universities!`);
}

main()
  .catch((e) => console.error(e))
  .finally(() => prisma.$disconnect());